    explanation: "## Two Chambers, One Loop\n\nA fish heart has **two chambers** — one atrium and one ventricle — and it drives a **single-loop** circulatory system.\n\nBlood is pumped from the heart to the gills, picks up oxygen, then flows through the body and back to the heart. There is only one pass through the heart per circuit.\n\nCompare this to birds and mammals, which have four chambers and two separate loops — one for the lungs, one for the body. Fish do not need two loops because they do not breathe air.\n\nWhenever the question asks about fish circulation, remember: single loop, two chambers, one pass through the heart per cycle.",
