    explanation: "## The Built-In Flotation Tank\n\nA bony fish can hover at any depth without swimming — a luxury that sharks do not have. The secret is the **swim bladder**.\n\nThe swim bladder is a gas-filled sac inside the body. By adjusting how much gas it contains, the fish can match its overall density to the water around it. This is *hydrostatic* control — the same principle a submarine uses.\n\nIn some species, the swim bladder also acts as a lung, allowing the fish to gulp air at the surface. Lungfish take this to an extreme, surviving dry seasons by breathing air.\n\nWhenever a question asks how bony fishes stay suspended, the answer is the swim bladder — not fins, not the heart, not the gills.",
