    explanation: "## Water Is Where It Begins\n\nAmphibians are tied to water for one key reason: their eggs. Most amphibians **lay their eggs in water**, and the larvae that hatch are aquatic.\n\nAmphibian eggs lack a shell. Without a shell, they dry out quickly. Water provides the moisture the embryo needs and lets the eggs develop safely.\n\nThis dependency is why frogs and toads are so common around ponds and streams, and why amphibian populations are so sensitive to wetland loss.\n\nWhenever you study amphibian reproduction, remember: eggs in water, larvae in water, adults on land. The cycle ties them to both environments.",
