    explanation: "## Basking for Warmth\n\nA lizard on a rock in the morning sun is not resting — it is warming up. Reptiles are **ectothermic**: they obtain heat from **external sources** like sunlight.\n\nEctothermy has real advantages. Ectotherms need far less food than endotherms of the same size, because they do not burn energy to make their own heat. A crocodile can go weeks without eating; a lion of the same weight must eat regularly.\n\nThe trade-off is that ectotherms are sluggish in the cold. That is why reptiles are most active in warm weather and least active at night or in winter.\n\nWhenever a question uses the word \"ectothermic,\" the answer is about external heat, not internal regulation.",
