    explanation: "## The Study of Birds\n\n**Ornithology** is the branch of zoology that studies birds. The name comes from the Greek *ornis* (bird) and *logos* (study).\n\nOrnithology is one of the oldest and most active branches of zoology. Birds are visible, vocal, and widespread, which makes them easy to observe and record. Amateur birdwatchers contribute to scientific data worldwide.\n\nOther vertebrate groups have their own -ology names: herpetology for reptiles and amphibians, ichthyology for fishes, mammalogy for mammals.\n\nWhenever you see -ology attached to an animal group, it means \"the study of.\" Ornithology is birds.",
