    correct: 3,
    explanation: "## Four Chambers, Two Loops\n\nA bird heart has **four chambers** — two atria and two ventricles — just like a mammal heart.\n\nThe four-chamber design separates oxygenated blood from deoxygenated blood. Blood returning from the lungs goes to the body; blood returning from the body goes to the lungs. The two never mix.\n\nThis matters for birds because flight is metabolically expensive. Clean separation of oxygenated blood means the muscles get the highest possible oxygen concentration — the fuel for sustained flight.\n\nWhenever you compare vertebrate hearts, remember the progression: two chambers (fishes), three (most amphibians), four (birds and mammals).",
