    explanation: "## The Water-Saving Waste\n\nBirds excrete **uric acid** — a semi-solid, pasty white material that comes out as the white part of bird droppings.\n\nUric acid has one great advantage: it is nearly insoluble in water. That means it can be excreted with very little water loss, which is essential for an animal that flies at high altitude and cannot afford to be heavy with water.\n\nCompare this to urea, which requires significant water, or ammonia, which requires even more. Uric acid is the most water-efficient option.\n\nWhenever a question asks about bird waste, remember: uric acid, not urea, not ammonia. The answer is about water conservation.",
