    correct: 1,
    explanation: "## The Hard-Shelled Egg\n\nBirds lay eggs with a **hard, calcareous shell** — the kind you see in a chicken egg.\n\nThe shell is mostly calcium carbonate. It is rigid, protective, and porous — porous enough to let air in and out, but strong enough to bear the weight of the incubating parent.\n\nThe hard shell evolved from the leathery shell of reptiles. The advantage is better protection against drying out, crushing, and microbial invasion. The cost is that the shell cannot stretch, so the egg is fixed in size.\n\nWhenever a question asks about bird eggs, remember: hard, calcareous, and laid in nests.",
