    explanation: "## Internal Fertilisation, External Development\n\nBirds use **internal fertilisation** — the male deposits sperm inside the female's reproductive tract, where it meets the egg before the shell is formed.\n\nThis is necessary because bird eggs have a hard shell. Once the shell is laid down, no sperm can penetrate it. Fertilisation must happen before the shell forms.\n\nThe pattern is different from amphibians, which fertilise externally in water. Birds separated the two events: fertilisation inside the mother, then a shell, then laying on land.\n\nWhenever you study bird reproduction, remember the sequence: internal fertilisation, shell formation, external laying and incubation.",
