    correct: 1,
    explanation: "## The Protein in Hair\n\nMammalian hair is made of **keratin** — a tough, fibrous protein. The same protein appears in horns, hooves, claws, feathers, and reptile scales.\n\nHair structure is unusual: the visible hair is made of dead cells, packed with keratin. The living part is at the base, in the follicle beneath the skin. This is why cutting your hair does not hurt.\n\nKeratin is what makes hair durable. It resists water, chemicals, and physical wear — which is why hair persists in the environment long after the animal has died.\n\nWhenever a question asks about the composition of hair, remember: keratin, made of dead cells, a protein-rich filament.",
