    explanation: "## The Egg-Laying Mammal\n\nThe **platypus** is one of the few monotremes — mammals that lay eggs. It is found in Australia and is famous for its unusual appearance: a duck-like bill, webbed feet, and a beaver-like tail.\n\nMonotremes are the only mammals that lay eggs. The eggs have a leathery shell, like those of reptiles, and the female usually lays two at a time. When the young hatch, they feed on milk that oozes from the mother's skin — monotremes have no nipples.\n\nThe platypus uses its webbed feet for swimming and its bill for scooping freshwater invertebrates from the bottom of streams.\n\nWhenever a question asks for an egg-laying mammal, remember: platypus (and the echidna). Not kangaroo, not elephant, not lion.",
