    correct: 1,
    explanation: "## Short Pregnancy, Long Pouch Life\n\nMarsupials have a **shorter gestation period** than placental mammals. The young is born early and finishes development outside the uterus.\n\nThis is possible because the marsupial placenta is **less developed and less efficient** than the placental mammal placenta. It cannot support the young for long, so the young has to leave early and continue in the pouch.\n\nThe trade-off is interesting. Placental mammals invest more in the uterus; marsupials invest more in the pouch. Both strategies work.\n\nWhenever a question compares reproduction in the two groups, remember: marsupials are the ones with short gestation and a pouch.",
