    correct: 3,
    explanation: "## The Bridge Between Water and Land\n\nAlgae live in water. Ferns and seed plants live on land with internal plumbing. Bryophytes sit between them.\n\nThey are **transitional forms** — the first plants that moved onto land but never fully left water behind. They have a waxy cuticle and air pores, but no true vascular tissue, and they still need water for reproduction.\n\nIn the evolutionary tree, bryophytes branch off after the green algae and before the vascular plants. They are not a stepping stone to ferns — they are a separate lineage that solved land life differently.\n\nWhenever you place a bryophyte in the plant kingdom, remember: after algae, before vascular plants.",
