    correct: 3,
    explanation: "## The Waxy Coat That Fights Drying\n\nMove from water to land, and the biggest threat is drying out. Bryophytes solve this with a **waxy cuticle** — a thin, water-repellent layer coating the epidermis.\n\nThe cuticle slows water loss from the plant surface. Without it, the plant would lose moisture to the air within hours and die.\n\nBut there is a catch. A water-tight surface also blocks gas exchange. That is why bryophytes also have **air pores** — openings in the cuticle that allow carbon dioxide in and oxygen out.\n\nThe cuticle and the air pores work together: one stops water, the other lets gas through.\n\nWhenever a question asks about the epidermis of a bryophyte, remember the waxy coat and the pores underneath it.",
