    correct: 2,
    explanation: "## Breathing Through Tiny Portholes\n\nThe waxy cuticle keeps water inside the bryophyte, but it also blocks the exchange of gases. Without a solution, the plant would suffocate inside its own waterproof coating.\n\nThe solution is **air pores** — small openings in the epidermis that let carbon dioxide in and oxygen out. They are the plant's breathing holes.\n\nIn liverworts like *Marchantia*, the air pores open into internal chambers below the surface, giving the gas exchange a larger surface area. In mosses, they are simpler but serve the same purpose.\n\nWhenever a question asks about bryophyte gas exchange, remember the pair: cuticle stops water, air pores let gas through.",
