    explanation: "## Why Water Is Non-Negotiable\n\nBryophytes need water for two separate reasons, and both are essential.\n\nFirst, they need water for **growth** — every cell depends on moisture to stay alive, and bryophytes have no internal plumbing to transport water from a distant source.\n\nSecond, they need water for **reproduction** — the sperm cells must swim through a film of moisture to reach the egg. No water means no fertilisation.\n\nThis is why bryophytes are described as amphibian plants: their entire life is tied to moisture, not just one stage.\n\nWhenever a question asks about bryophyte water dependency, remember the pair: growth and reproduction.",
