    explanation: "## Surviving the Dry Spell\n\nMost bryophytes live in moist habitats. But a few species survive in arid areas with little or no rainfall — and they do it by going dormant.\n\nWhen the environment dries out, these bryophytes **enter a dormant state**. Their metabolism slows to almost nothing, and their tissues lose most of their water. They look dead.\n\nWhen rain finally arrives, the plants rehydrate within hours and resume normal function. This ability to suspend life is called **desiccation tolerance**, and it is one of the most remarkable adaptations in the plant kingdom.\n\nWhenever a question asks how bryophytes survive drought, remember: they do not fight the dry — they wait it out.",
