    explanation: "## The Growing Tip\n\nIn mosses, the sex organs — **antheridia and archegonia** — develop at the **apex of the moss stems**.\n\nThe apex is the growing tip of the plant. In mosses, it is often surrounded by a cluster of leaves called a **rosette**, which protects the developing sex organs.\n\nThe antheridia produce sperm cells; the archegonia contain egg cells. Water is essential for fertilisation, because the sperm must swim from the antheridium to the archegonium through a film of moisture.\n\nThis is why mosses reproduce only when conditions are wet. In dry weather, the sex organs are present but the sperm cannot travel.\n\nWhenever a question asks where moss sex organs are located, remember: at the apex, at the tip of the stem.",
