    explanation: "## The Moisture Trigger\n\nThe peristome teeth of a moss capsule are hygroscopic — they respond to moisture.\n\nIn **dry weather**, the teeth bend outward and open the capsule mouth. The spores are then free to be carried away by the wind.\n\nIn **wet weather**, the teeth bend inward and close the mouth. The spores stay inside, protected from the rain that would wash them into unsuitable places.\n\nThe system is elegant. The plant lets the weather decide when to release its spores, using moisture as a simple but reliable signal.\n\nWhenever a question asks what triggers spore release, remember: dry weather opens the teeth; wet weather closes them.",
