    explanation: "## The Canary in the Moss\n\nA bioindicator is an organism whose presence or absence tells you something about the environment. Bryophytes are excellent bioindicators.\n\nWhy? Because they absorb water and nutrients directly through their surfaces, without a root system or a selective filter. Whatever is in the air or water — including pollutants — enters the plant.\n\nSome moss species are extremely sensitive to sulphur dioxide and other air pollutants. When pollution rises, these species disappear. Their absence is a warning sign that the air quality has degraded.\n\nWhenever a question asks why bryophytes are used as bioindicators, remember: sensitive species vanish first in polluted areas.",
