    explanation: "## The Small Plants That Store Big Carbon\n\nA single moss plant contains almost no carbon. But mosses cover vast areas — forest floors, wetlands, tundra — and together they store an enormous amount of carbon.\n\nThey act as a **carbon sink**: they take carbon dioxide out of the atmosphere through photosynthesis and lock it into their tissues. When the moss dies and decomposes slowly (as in a bog), the carbon stays locked in the soil for centuries.\n\nPeat bogs, built up from layers of Sphagnum, hold more carbon per hectare than most forests. This is one reason wetland conservation matters for climate.\n\nWhenever a question asks about bryophytes and carbon, remember: they are a sink, not a source.",
