    correct: 2,
    explanation: "## Anchor and Straw Combined\n\nA rhizoid is a single, thin filament. It can hold a tiny plant in place, and it can absorb a little water — but only from the surface it sits on.\n\nA **true root** does the same two jobs, but much better. It branches. It penetrates deeper. It reaches water that a rhizoid can never touch. And it anchors the plant against wind, animals, and runoff that would pull a shallow rhizoid free.\n\nThis is why pteridophytes can grow taller than bryophytes. They have a root system that can support a bigger, heavier plant.\n\nWhenever a question compares rhizoids and roots, remember: same two jobs — anchorage and absorption — but roots do both better.",
