    explanation: "## Small and Simple\n\nA microphyll — the leaf type of fern allies — is defined by one thing: a **single, unbranched vein** running through it. That is the whole vascular supply for the leaf.\n\nBecause the vein does not branch, the leaf cannot support a large blade. That is why microphylls are always small: a few millimetres to a couple of centimetres. Anything larger would not get enough water.\n\nSo when you see a fern ally — a club moss or a horsetail — you are looking at a plant with tiny, simple leaves, each with its own single strand of vascular tissue.\n\nWhenever a question asks about fern ally leaves, remember: microphylls — small, with a single vein.",
