    explanation: "## A Mature Ovule\n\nA seed starts life as an **ovule** — an egg-containing structure on the parent plant. After fertilisation, the ovule matures into a seed.\n\nThat mature seed contains three parts. The **embryo** is the young plant. The **endosperm** is the stored food. The **seed coat** is the protective outer layer.\n\nThe seed coat is what makes the seed so much tougher than a spore. It resists drying, temperature change, and digestion. That is why seeds can travel through animal guts, sit in soil for years, and germinate when conditions finally improve.\n\nWhenever a question asks what a seed is, remember: a mature ovule with three parts.",
