    explanation: "## Three Parts, One Job\n\nA seed has three parts. Each does one job.\n\nThe **embryo** is the new plant — a miniature sporophyte with root and shoot tips already formed. The **endosperm** is food: starch, oils, and proteins that will feed the embryo until it can photosynthesise on its own. The **seed coat** is armour that protects everything inside.\n\nIf any part is missing, the seed fails. No embryo means no plant. No endosperm means the seedling starves. No coat means the seed dries out before it can germinate.\n\nWhenever a question asks about the three parts of a seed, remember: embryo, endosperm, coat.",
