    correct: 2,
    explanation: "## Ducts of Resin\n\nPine stems contain **resin canals** — narrow tubes lined with cells that secrete resin. The resin oozes out when the tree is wounded, sealing the cut and discouraging insects and fungi.\n\nThese canals run through two regions of the stem: the **xylem** (the wood) and the **cortex** (the tissue just under the bark). You can see them as small, clear ducts in a cross-section of pine wood.\n\nResin is commercially useful. Turpentine and rosin are both derived from pine resin, and resin collection is still practised in some regions.\n\nWhenever a question asks where resin canals occur, remember: xylem and cortex.",
