    correct: 2,
    explanation: "## One Cell Wide\n\nA medullary ray is a ribbon of parenchyma cells that runs radially through the wood — from the pith outward toward the bark. Rays store food and move it sideways through the stem.\n\nIn pine, the rays are **uniseriate** — a single cell wide. In other trees, rays can be biseriate (two cells wide) or multiseriate (many cells wide).\n\nUniseriate rays are one of the features that help identify pine wood under the microscope. Combined with tracheid-only xylem and prominent bordered pits, they give conifer wood its characteristic appearance.\n\nWhenever a question asks about pine rays, remember: uniseriate — one cell wide.",
