    explanation: "## Drought When Water Is Everywhere\n\n*Physiological drought* sounds like a contradiction. Drought means water shortage; physiology means the body. How can a plant be in drought while sitting in moisture?\n\nThe answer is temperature. When the soil is frozen, water is present but locked as ice. The plant cannot absorb it. The result is the same as if the soil were dry — the pine is starved of water, even though the ground around it is full of H₂O.\n\nThis happens in temperate and boreal forests every winter. Pines survive it because their needle adaptations — thick cuticles, sunken stomata, hypodermis — slow water loss to a trickle during frozen months.\n\nWhenever a question asks about physiological drought, remember: water present, but frozen and unusable.",
