    explanation: "## A Species Signature\n\nA fascicle is the small bundle that holds pine needles. The number of needles per fascicle is a **stable, species-specific feature**.\n\n*Pinus monophylla* has one needle per fascicle. *Pinus sylvestris* has two. *Pinus insularis* has three. These counts do not change from tree to tree within a species — they are part of what defines the species.\n\nThat is why taxonomists use fascicle count as one of the first characters to check when identifying an unknown pine. It is quick, reliable, and does not require the tree to be flowering or fruiting.\n\nWhenever a question asks about fascicle count, remember: it identifies the species.",
