    explanation: "## The First Leaves\n\nWhen a seed germinates, the first leaves to appear are not the plant's true leaves. They are the **cotyledons** — the embryonic seed leaves that were already present inside the seed.\n\nCotyledons often look nothing like the plant's later leaves. They may be rounder, thicker, or paler. Their job is temporary: to supply food to the seedling until true leaves emerge and start photosynthesising.\n\nThe number of cotyledons is one of the most important ways to classify flowering plants. Two cotyledons means a dicot. One means a monocot. That distinction shapes the entire course of the plant's life — from leaf veins to root structure to flower parts.\n\nWhenever a question asks about a seedling's first leaves, remember: the cotyledons.",
