    explanation: "## The Name Says Two\n\n*Dicot* comes from two Greek roots: *di* (two) and *kotyledon* (seed leaf). The name literally means \"two seed leaves.\"\n\nPeanuts, tomatoes, beans, and most shrubs and trees are dicots. If you split a bean seed open, you can see the two fleshy halves — those are the cotyledons, packed with food for the seedling.\n\nThe two-cotyledon pattern goes with other features: net-like leaf veins, tap roots, and floral parts usually in fours or fives. Botanists use the cotyledon number as the first clue to the whole plant's structure.\n\nWhenever a question asks about dicot cotyledons, remember: two — the name tells you.",
