    explanation: "## The Last Act\n\nAn annual plant has one growing season to live. It germinates, grows, flowers, produces seeds, and dies — all within a few months.\n\nFlowers appear **near the end of the life cycle**, after the plant has built enough size and stored enough resources. The plant is not being wasteful; it is being strategic. By waiting until it has grown, it can invest its full energy into seeds that will survive the next season.\n\nIn perennials, flowering may happen year after year. But the timing is still the same: it follows growth, it does not precede it.\n\nWhenever a question asks when flowering happens, remember: after growth — near the end of the cycle in annuals.",
