    explanation: "## Two Halves of the Axis\n\nThe main axis of a plant is divided into two systems: the **root system** below ground, and the **shoot system** above ground.\n\nThe root system anchors the plant and absorbs water and minerals. The shoot system grows upward, produces leaves for photosynthesis, and eventually flowers.\n\nThe two systems are connected by vascular tissue, which moves water up and food down. Neither can survive without the other. Cut the connection and the plant dies within days.\n\nWhenever a question asks about the two systems, remember: root and shoot.",
