    explanation: "## Soft-Stemmed Plants\n\nHerbs are soft-stemmed plants. The reason is structural: their stems contain a **higher proportion of parenchyma** — soft, thin-walled packing tissue — than **xylem**, the hard, woody water-conducting tissue.\n\nBecause there is little xylem, herbs have no hard woody core. Their stems bend easily, die back at the end of the season, and rely on underground organs or seeds to survive the winter.\n\nSunflower and Tithonia are typical Zambian herbs. They grow fast and tall in the wet season, then die when the season ends.\n\nWhenever a question asks what makes an herb an herb, remember: mostly parenchyma, little xylem — a soft, non-woody stem.",
