    explanation: "## Two Years, One Flower\n\nA **biennial** plant takes two years to complete its life cycle.\n\nThe first year is spent growing — building leaves, stems, and roots. The plant stays vegetative; it does not flower. Then it survives the winter, often as a rosette of leaves close to the ground.\n\nIn the second year, the plant flowers, produces seed, and dies. It does not get a third year.\n\nSpinach is a classic biennial in the source material. It remains vegetative for two years under some conditions and dies after producing flowers and seeds at the end of the second year.\n\nWhenever a question asks about biennials, remember: two years — grow first, flower second, then die.",
