    explanation: "## The Best Soil for Roots\n\nRoots grow best in **well drained moist soils**. The combination matters on both counts.\n\n*Moist* means there is water available. *Well drained* means that water is not stagnant — it moves through the soil, carrying oxygen with it. Roots need oxygen for respiration, just like leaves do.\n\nSoil that is too dry starves the roots of water. Soil that is too wet drowns them. Neither produces the extensive, branching root system of a healthy plant.\n\nWhenever a question asks about root development, remember: well drained and moist — both conditions together.",
