    correct: 0,
    explanation: "## The Growing Point\n\nAt the tip of every root is a small region of actively dividing cells called the **apical meristem**. It is the source of all new root tissue.\n\nThe apical meristem produces cells in three directions: forward, to renew the root cap; sideways, to expand the root's girth; and backward, to add length to the root body.\n\nBehind the meristem, the new cells differentiate into the specialised tissues that make up the mature root — epidermis, cortex, endodermis, and vascular tissue.\n\nWhenever a question asks what governs root growth, remember: the apical meristem.",
