    correct: 0,
    explanation: "## The Slime Coat\n\nThe root cap is a small cap of **parenchyma cells** covering the growing tip of the root. These cells do two jobs.\n\nFirst, they protect the delicate apical meristem as the root pushes through soil. Particles of sand and stone would otherwise scrape and damage the growing cells.\n\nSecond, the outer root cap cells secrete **mucigel** — a slimy polysaccharide that lubricates the root tip and helps it slide between soil particles.\n\nMucigel is also rich in carbohydrates and amino acids, so it feeds beneficial microbes around the root. The plant is essentially laying a slime trail that invites helpful bacteria and fungi.\n\nWhenever a question asks about the root cap, remember: parenchyma cells that secrete mucigel.",
