    correct: 0,
    explanation: "## The Inner Boundary\n\nIn a dicot root, the vascular cylinder — with its xylem arms and phloem strands — is surrounded by the **endodermis**.\n\nThe endodermis is a single layer of cells, but it does something crucial. Each cell has a **Casparian strip** — a band of suberin, a waxy substance — running around its radial and transverse walls.\n\nThe strip blocks water from passing between endodermal cells. All water and minerals entering the vascular cylinder must pass *through* the cells, where the plant can control what enters. It is a security checkpoint between soil and vascular tissue.\n\nWhenever a question asks what surrounds the vascular cylinder in a dicot root, remember: the endodermis.",
