    correct: 1,
    explanation: "## Dispersal by Stem Cuttings\n\nSome plants spread by their stems — not by seed. Cassava and sweet potato are two examples.\n\nWhen a cassava stem touches the ground, it can produce roots and grow into a new plant. Farmers take advantage of this: they cut cassava stems into sections and plant them. Each section becomes a new plant.\n\nSweet potato works the same way. Sections of vine with nodes can root and grow into new plants. This is why these crops are called *vegetatively propagated*.\n\nVegetative dispersal is fast and reliable. A cutting is genetically identical to the parent, so the new plant has all the parent's desirable traits. Farmers can spread a good variety through a field without waiting for seed.\n\nWhenever a question asks about stem-based dispersal, remember: cassava and sweet potato.",
    status: "approved"
