    explanation: "## Nodes and Internodes\n\nA stem has a repeating structure. Along its length, you find two alternating regions: **nodes** and **internodes**.\n\nA **node** is a point where leaves, buds, or branches attach. You can find it by looking for where a leaf joins the stem.\n\nAn **internode** is the stretch of stem between two nodes. It is the elongating region — when a stem grows taller, it is the internodes that stretch.\n\nThis pattern repeats along every stem. It is one of the simplest ways to tell a stem from a root: roots do not have nodes and internodes.\n\nWhenever a question asks about stem divisions, remember: nodes and internodes.",
