    explanation: "## IAA from the Tip\n\nThe terminal bud at the tip of a stem produces **indole acetic acid**, or **IAA**. IAA is an auxin — a class of plant hormones that regulate growth.\n\nIAA is made in the young cells at the stem apex and travels downward. Its concentration is highest at the tip and decreases down the stem.\n\nIAA is a derivative of the amino acid tryptophan. That is a useful detail for exams — the plant builds its most important growth hormone from one of the twenty amino acids.\n\nWhenever a question asks about the hormone from the terminal bud, remember: indole acetic acid — IAA.",
