    correct: 2,
    explanation: "## Apical Dominance\n\nThe terminal bud produces IAA, and IAA moves down the stem. When it reaches the lateral buds — the buds sitting in the leaf axils — it **inhibits their development**.\n\nThis phenomenon is called **apical dominance**. The apical bud suppresses the growth of the buds below it, so the plant grows tall rather than bushy.\n\nWhy would a plant do this? Because height matters. In a crowded forest, the tallest plant gets the most light. Apical dominance lets the shoot invest in height first, then branch later.\n\nWhenever a question asks about IAA and lateral buds, remember: it inhibits them.",
