    explanation: "## The Floral Bracts\n\nHypophylls are modified leaves associated with flowers. Another name for them is **floral bracts**.\n\nThey sit near the base of a flower or an inflorescence, often looking different from the plant's normal leaves. Sometimes they are green and small. Sometimes they are brightly coloured and showy — the red 'petals' of a poinsettia are actually floral bracts, not petals.\n\nTheir jobs are protection and, in some species, pollinator attraction. They shield the developing flower and sometimes carry the colour that draws the pollinator in.\n\nWhenever a question asks about floral bracts, remember: hypophylls.",
