    explanation: "## Two Parts, One Leaf\n\nA leaf has two parts: the **petiole** and the **blade**.\n\nThe petiole is the stalk. It attaches the leaf to the stem and positions the blade toward the light. Inside the petiole, vascular tissue runs from stem to blade.\n\nThe blade — also called the lamina — is the broad, flat part. It carries the chlorophyll, the stomata, and the mesophyll. It is where photosynthesis happens.\n\nSome leaves skip the petiole and attach directly to the stem. But the basic two-part structure — stalk plus blade — is the standard pattern.\n\nWhenever a question asks about the parts of a leaf, remember: petiole and blade.",
