    explanation: "## The Upright Workers\n\nPalisade cells are long, columnar cells packed just under the upper epidermis. They are the leaf's main photosynthetic factory.\n\nWhy are they on top? Because that is where the light hits first. Their tall shape lets them pack in more chloroplasts per unit of surface, and their position directly under the upper epidermis means almost no light is lost before reaching them.\n\nBelow them, the loosely packed spongy cells catch the remaining light and handle gas exchange. But the palisade layer does the heavy lifting.\n\nWhenever a question asks which cells do the primary photosynthesis, remember: palisade mesophyll.",
