    explanation: "## Room to Breathe\n\nSpongy cells are irregularly shaped and loosely arranged. Between them are large air spaces — and those spaces are the point.\n\nCarbon dioxide enters through stomata, travels through the air spaces, and reaches the photosynthetic cells from every direction. Oxygen produced by photosynthesis escapes the same way. Without the air spaces, the gas would have to diffuse through tightly packed cells — far too slow.\n\nThe spongy layer is like a foam: mostly space, held together by scattered cells. That structure is what lets gas move quickly through the leaf interior.\n\nWhenever a question asks about loosely arranged cells with air spaces, remember: spongy mesophyll.",
