    explanation: "## Water on Top\n\nIn a dicot leaf, each vascular bundle has the xylem on its **adaxial** side — the upper side, facing toward the sun.\n\nThe phloem sits on the **abaxial** side — the lower side, facing the ground.\n\nWhy this arrangement? It reflects the direction of the veins' supply. Water comes up from the roots into the xylem, which sits in the upper half of the vein. Sugars made in the mesophyll enter the phloem on the lower half and travel back down the plant.\n\nThis \"xylem up, phloem down\" pattern is a reliable feature of dicot leaves. It shows up clearly in transverse sections used in botany labs.\n\nWhenever a question asks about xylem position in a leaf vein, remember: adaxial — upper side.",
