    correct: 0,
    explanation: "## Naming the Two Sides\n\nA leaf has two faces, and botanists use precise names for them.\n\nThe **adaxial** side faces toward the stem and usually upward. It is the side that catches the most sunlight and often has a thicker cuticle.\n\nThe **abaxial** side faces away from the stem and usually downward. It typically has more stomata, since the underside stays cooler and loses less water.\n\nBoth terms come from Latin: *ad* (toward) and *ab* (away from) *axis* (the stem axis). Adaxial faces the axis; abaxial faces away.\n\nWhenever a question asks about the upper leaf surface, remember: adaxial.",
