    explanation: "## Slicing Through a Leaf\n\nA **TS** — transverse section — is a cross-section cut perpendicular to the leaf surface. Under a microscope, it reveals the full internal structure.\n\nFour layers become visible. The **upper epidermis** is a single clear layer. Below it, the **palisade mesophyll** shows tightly packed, tall green cells. Then the **spongy mesophyll** with its irregular cells and air spaces. And finally the **lower epidermis**, punctuated by stomata.\n\nRunning between the spongy cells, the **vascular bundles** appear as dark spots — the veins of the leaf.\n\nWhenever a question asks what a TS of a dicot leaf reveals, remember: all the main tissue layers — epidermis, palisade, spongy, veins.",
