    explanation: "## The Supporting Cast\n\nSubsidiary cells are specialised epidermal cells that surround the guard cells. They sit beside the pore like a frame around a door.\n\nThey do more than cosmetic work. Subsidiary cells help move ions and water into and out of the guard cells, supporting the opening and closing mechanism. Some also help regulate the ion balance that keeps the stoma functioning.\n\nIn many plant species, the number and arrangement of subsidiary cells is used to classify the type of stomatal complex — a taxonomic character like the peristome teeth of mosses.\n\nWhenever a question asks which cells surround and support guard cells, remember: subsidiary cells.",
