    explanation: "## The Waiting Years\n\nJuvenility is the early phase of a plant's life when it cannot flower — no matter what you do to it. No hormone spray, no change in day length, no fertiliser will trigger flowering during this phase.\n\nThe plant must pass through juvenility before it becomes reproductively capable. Only then does the flowering phase begin.\n\nThis phase matters commercially. A mango tree may take five to seven years to fruit — because that is how long its juvenility lasts. Bamboo can take decades. The length of juvenility is part of what makes some crops easy and others slow to establish.\n\nWhenever a question asks about the pre-flowering phase, remember: juvenility.",
