    explanation: "## A Short Childhood\n\nAn annual plant lives for one season. If its juvenility lasted years, the plant would die before it ever flowered.\n\nSo annuals have very short juvenility — a few days, a few weeks, or a few months. Maize germinates and flowers within about eight weeks. Wheat often flowers in six. Their juvenility is compressed into a fraction of the growing season.\n\nThis is a strategy for speed. Annuals are the sprinters of the plant world — they start fast, flower fast, seed fast, and die. Their entire life cycle is built around a single window of opportunity.\n\nWhenever a question asks about juvenility in annuals, remember: days to months — very short.",
