    correct: 0,
    explanation: "## A Whole Branch of Flowers\n\nAn inflorescence is not a single flower. It is a **fertile shoot that bears a cluster of flowers** — several blooms arranged on one specialised branch system.\n\nThat is why a sunflower head looks like one flower but is actually dozens of tiny flowers packed together. It is why a lupine has a tall spike of blooms instead of just one. The inflorescence is the whole arrangement.\n\nInflorescences matter because they increase pollination efficiency. A cluster of flowers is more visible to pollinators than a single bloom, and it releases more pollen into the air for wind-pollinated species.\n\nWhenever a question asks about a cluster of flowers, remember: inflorescence.",
