    explanation: "## Two Stalks, Two Names\n\nEvery inflorescence sits on a stalk. That main stalk is called the **peduncle**.\n\nThe peduncle attaches the whole flower cluster to the main stem of the plant. It is like the trunk of a small tree — every branch of the inflorescence grows from it.\n\nCompare with the **pedicel** — the stalk of a single flower. Pedicels branch off from the peduncle, one for each flower in the cluster.\n\nSo the rule is simple: peduncle holds the whole cluster, pedicel holds one flower.\n\nWhenever a question asks about the whole inflorescence stalk, remember: the peduncle.",
