    explanation: "## No Stalks at All\n\nA spike looks like a raceme — a long central axis with flowers along it. But there is one structural difference.\n\nIn a raceme, each flower sits on a pedicel. In a spike, the flowers have **no pedicels**. They attach directly to the axis. Sessile, not stalked.\n\nThat is why wheat and plantain look so tightly packed: without pedicels between them, the flowers crowd together on the stem. The result is a dense, compact inflorescence.\n\nWhenever a question asks how to tell a spike from a raceme, remember: spike has no pedicels — raceme has pedicels.",
